package com.gymflow.app;
import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import org.json.*; import java.util.*;
public class CreateRoutineActivity extends AppCompatActivity{
 private LinearLayout exerciseBox; private ArrayList<String> equipment=new ArrayList<>();
 @Override protected void onCreate(Bundle b){super.onCreate(b);ScrollView s=new ScrollView(this);LinearLayout r=Ui.page(this);s.addView(r);Ui.backHeader(this,r,"Crear rutina");r.addView(Ui.subtitle(this,"La rutina se arma usando el equipamiento real cargado por este gimnasio."));EditText name=Ui.input(this,"Nombre de la rutina");r.addView(name);Spinner goal=Ui.spinner(this,new String[]{"Hipertrofia","Bajar de peso","Fuerza","Resistencia","Mantenimiento"});r.addView(goal);Spinner level=Ui.spinner(this,new String[]{"Principiante","Intermedio","Avanzado"});r.addView(level);Spinner days=Ui.spinner(this,new String[]{"2","3","4","5","6"});days.setSelection(1);r.addView(days);CheckBox own=new CheckBox(this);own.setText("Usar solo el equipamiento de este gimnasio");own.setTextColor(getColor(R.color.gf_text));own.setChecked(true);r.addView(own);r.addView(Ui.subtitle(this,"Equipamiento disponible y sugerencias:"));exerciseBox=new LinearLayout(this);exerciseBox.setOrientation(LinearLayout.VERTICAL);r.addView(exerciseBox);loadEquipment();Button build=Ui.button(this,"Guardar rutina online");build.setOnClickListener(v->{try{String n=name.getText().toString().trim();if(n.isEmpty())n="Rutina personalizada";JSONObject o=new JSONObject();o.put("owner_id",Session.uid(this));o.put("name",n);o.put("goal",goal.getSelectedItem().toString());o.put("level",level.getSelectedItem().toString());o.put("days",Integer.parseInt(days.getSelectedItem().toString()));o.put("equipment_only",own.isChecked());Cloud.post(this,"gf_routines",o,(c,b)->{if(c>=200&&c<300){Toast.makeText(this,"Rutina guardada online",Toast.LENGTH_SHORT).show();finish();}else Toast.makeText(this,Cloud.err(b),Toast.LENGTH_LONG).show();});}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}});r.addView(build);setContentView(s);}
 private void loadEquipment(){exerciseBox.removeAllViews();Cloud.get(this,"gf_equipment","select=name&owner_id=eq."+Session.uid(this)+"&available=eq.true&order=name.asc",(c,b)->{try{JSONArray a=new JSONArray(b);if(a.length()==0){exerciseBox.addView(Ui.card(this,"Sin equipamiento","Cargalo primero para personalizar las rutinas."));return;}for(int i=0;i<a.length();i++){String e=a.getJSONObject(i).optString("name");equipment.add(e);exerciseBox.addView(Ui.card(this,suggestExercise(e),e));}}catch(Exception e){exerciseBox.addView(Ui.card(this,"Error",Cloud.err(b)));}});}
 private String suggestExercise(String e){String z=e.toLowerCase();if(z.contains("prensa"))return "Prensa de piernas";if(z.contains("hack"))return "Sentadilla Hack";if(z.contains("smith"))return "Sentadilla en Smith";if(z.contains("polea alta"))return "Jalón al pecho";if(z.contains("polea baja"))return "Remo en polea baja";if(z.contains("banco plano"))return "Press de banca";if(z.contains("inclinado"))return "Press inclinado";if(z.contains("scott"))return "Curl en banco Scott";if(z.contains("cuádriceps"))return "Extensión de cuádriceps";return "Ejercicio compatible";}
}
